import '../../../core/network/api_client.dart';import 'medication_models.dart';class MedicationRepository{MedicationRepository(this._client);final ApiClient _client;Future<List<Medication>> getAll()async{final r=await _client.dio.get<List<dynamic>>('/api/medications');return r.data!.map((e)=>Medication.fromJson(e)).toList();}Future<Medication> create(String name,String? dosage,String? instructions)async{final r=await _client.dio.post<Map<String,dynamic>>('/api/medications',data:{'name':name,'dosage':dosage,'instructions':instructions});return Medication.fromJson(r.data!);}Future<void> addSchedule(String id,String time,String frequency,String startDate,String? endDate) => _client.dio.post<void>('/api/medications/'+id+'/schedules',data:{'time':time,'frequency':frequency,'startDate':startDate,'endDate':endDate});
  Future<void> log(String id,String scheduledTime,String status) => _client.dio.post<void>('/api/medications/'+id+'/logs',data:{'scheduledTime':scheduledTime,'takenAt':status=='Taken'?DateTime.now().toUtc().toIso8601String():null,'status':const ['Taken','Missed','Skipped'].indexOf(status)+1});
  Future<void> setStatus(String id,bool active)=>_client.dio.patch<void>('/api/medications/'+id+'/status',queryParameters:{'isActive':active});Future<MedicationAdherence> adherence()async{final r=await _client.dio.get<Map<String,dynamic>>('/api/medications/adherence-summary');return MedicationAdherence.fromJson(r.data!);}}